
const User = require('../models/userModel');

// 1. Récupérer tous les articles avec les données complètes de l'auteur
const getAllArticles = async (req, res) => {
  try {
    const articles = await Article.find().populate('author', 'name email');
    res.status(200).json(articles);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};

// 2. Récupérer un article unique par son ID
const getArticleById = async (req, res) => {
  try {
    const article = await Article.findById(req.params.id);
    if (!article) {
      return res.status(404).json({ message: 'Article non trouvé' });
    }
    return res.status(200).json(article);
  } catch (err) {
    // Vérification de l'erreur CastError
    if (err.name === 'CastError') {
      return res.status(400).json({
        message: 'Invalid resource identifier (ObjectId expected)'
      });
    }
    return res.status(500).json({ message: err.message });
  }
};

// 3. Créer un nouvel article lié à un auteur
const createArticle = async (req, res) => {
  try {
    const { title, content, authorId } = req.body;

    if (!title || !content || !authorId) {
      return res.status(400).json({
        message: 'title, content et authorId sont obligatoires'
      });
    }

    // Vérifier l’existence réelle de l’auteur dans la collection 'users'
    const author = await User.findById(authorId);
    if (!author) {
      return res.status(404).json({
        message: 'Auteur non trouvé (identifiant authorId invalide)'
      });
    }

    const newArticle = await Article.create({
      title,
      content,
      author: authorId
    });

    const populatedArticle = await newArticle.populate('author', 'name email');
    res.status(201).json(populatedArticle);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};

// 4. Mettre à jour un article (PUT /api/articles/:id)
const updateArticle = async (req, res) => {
  try {
    const article = await Article.findByIdAndUpdate(
      req.params.id,
      req.body,
      { new: true, runValidators: true } // Renvoie le doc mis à jour et applique les validations Mongoose
    );

    if (!article) {
      return res.status(404).json({ message: 'Article introuvable pour la mise à jour' });
    }

    const populated = await article.populate('author', 'name email');
    res.status(200).json(populated);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};

// 5. Supprimer un article (DELETE /api/articles/:id)
const deleteArticle = async (req, res) => {
  try {
    const article = await Article.findByIdAndDelete(req.params.id);

    if (!article) {
      return res.status(404).json({
        message: `Impossible de supprimer : article ${req.params.id} introuvable`
      });
    }

    res.status(200).json({ message: 'Article supprimé avec succès' });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
};

module.exports = {
  getAllArticles,
  getArticleById,
  createArticle,
  updateArticle,
  deleteArticle
};